aggregation.evalscript:
//VERSION=3
function setup() { return { input: [{bands: ["B04","B08","SCL","dataMask"]}], output: [{id:"ndvi", bands:1, sampleType:"FLOAT32"},{id:"dataMask", bands:1}] }; }
function evaluatePixel(s) { let bad = [3,8,9,10,11].includes(s.SCL); return { ndvi: [(s.B08 - s.B04)/(s.B08 + s.B04)], dataMask: [(s.dataMask === 1 && !bad) ? 1 : 0] }; }
